(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zh-sj-prepa-med-j3-ide"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zh-sj-prepa-med-j3-ide\",\n \"titre\": \"Préparation D.E (J) · J3 Médecine IDE\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 46,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n   \"sha256\": \"45110ca169c7b815e8c5983cb6aa915440763cce1306bb015109584afb42df7f\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Médecine · Prépa D.E J3 (IDE)\",\n     \"slug\": \"prepa-med-j3-ide\",\n     \"pages\": \"\",\n     \"count\": 46,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Médecine\",\n     \"source\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__0\",\n       \"num\": \"1\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ETUDE DE CAS : En service au CHU de Treichville, vous avez en charge ce jour M. Sangaré, âgé de 45 ans pour une taille de 1,70 m. Il est très affaibli, a une langue pâteuse, se plaint de céphalées et de douleurs diverses. Il refuse de manger. Sa température est de 40°C, une TA de 11/7 cmHg pour un pouls de 100 puls/mn.\",\n       \"text\": \"A quelle affection pensez-vous ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Paludisme\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Méningite\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Fièvre typhoïde\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Paludisme\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Fièvre à 40 °C, céphalées, douleurs diverses (courbatures), grande fatigue et refus de manger : c'est le tableau du paludisme simple décrit dans le cours (fièvre, céphalées, myalgies, troubles digestifs, asthénie). Sans raideur de la nuque ni troubles de conscience, la méningite est peu probable ; la langue pâteuse peut faire penser à la typhoïde, mais le pouls à 100 n'est pas « dissocié ».\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Paludisme – IV Étude clinique 4-1 (p. 50)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__1\",\n       \"num\": \"2\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ETUDE DE CAS : En service au CHU de Treichville, vous avez en charge ce jour M. Sangaré, âgé de 45 ans pour une taille de 1,70 m. Il est très affaibli, a une langue pâteuse, se plaint de céphalées et de douleurs diverses. Il refuse de manger. Sa température est de 40°C, une TA de 11/7 cmHg pour un pouls de 100 puls/mn.\",\n       \"text\": \"Quels sont les signes qui militent en faveur de votre diagnostic ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Tension artérielle\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Céphalées\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Fièvre\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Myalgie\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Pouls\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Asthénie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Fièvre ; D. Myalgie ; E. Pouls\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"La fièvre (40 °C), les myalgies (« douleurs diverses ») et le pouls accéléré (100/mn, en rapport avec la fièvre) font partie du tableau du paludisme. La tension artérielle (11/7) est normale et n'oriente pas.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Paludisme – 4-1 Paludisme simple (p. 50)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__2\",\n       \"num\": \"3\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ETUDE DE CAS : En service au CHU de Treichville, vous avez en charge ce jour M. Sangaré, âgé de 45 ans pour une taille de 1,70 m. Il est très affaibli, a une langue pâteuse, se plaint de céphalées et de douleurs diverses. Il refuse de manger. Sa température est de 40°C, une TA de 11/7 cmHg pour un pouls de 100 puls/mn.\",\n       \"text\": \"Parmi les examens ci-dessous demandés par le médecin, lequel est à propos ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Goutte épaisse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"NFS\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"PL\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Goutte épaisse\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La goutte épaisse (avec le frottis) met en évidence le Plasmodium et permet de préciser l'espèce et la densité parasitaire : c'est l'examen adapté. La NFS n'est qu'un examen d'orientation et la PL servirait à rechercher une méningite.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Paludisme – VI Diagnostic biologique (p. 51) ; Documents de révision L3 Médecine, paludisme (items 15-16)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__3\",\n       \"num\": \"4\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ETUDE DE CAS : En service au CHU de Treichville, vous avez en charge ce jour M. Sangaré, âgé de 45 ans pour une taille de 1,70 m. Il est très affaibli, a une langue pâteuse, se plaint de céphalées et de douleurs diverses. Il refuse de manger. Sa température est de 40°C, une TA de 11/7 cmHg pour un pouls de 100 puls/mn.\",\n       \"text\": \"Quelles sont les complications qui peuvent être liées à cette affection ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Ictère\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Abcès du foie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Hémorragie digestive\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Anémie\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Encéphalite\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Ictère ; D. Anémie\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\"\n       ],\n       \"explanation\": \"L'ictère et l'anémie sévère (Hb < 5 g/dl) font partie des critères du paludisme grave, donc des complications du paludisme. L'abcès du foie relève de l'amibiase et l'encéphalite, comme complication classique, de la fièvre typhoïde. Remarque : Le cours cite aussi les « hémorragies diffuses (épistaxis, méléna) » parmi les signes de gravité ; l'option « hémorragie digestive » n'est pas retenue par la correction nationale.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), 4-2 Critères du paludisme grave (p. 50) ; Cours de maladies infectieuses et parasitaires, 4-2 Paludisme grave\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__4\",\n       \"num\": \"5\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ETUDE DE CAS : En service au CHU de Treichville, vous avez en charge ce jour M. Sangaré, âgé de 45 ans pour une taille de 1,70 m. Il est très affaibli, a une langue pâteuse, se plaint de céphalées et de douleurs diverses. Il refuse de manger. Sa température est de 40°C, une TA de 11/7 cmHg pour un pouls de 100 puls/mn.\",\n       \"text\": \"Sachant que M. Sangaré a un IMC de 17,30, quel est son poids ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"49 Kg\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"50 Kg\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"51 Kg\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 50 Kg\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Poids = IMC × taille² = 17,30 × (1,70)² = 17,30 × 2,89 ≈ 50 kg. (explication hors cours du projet : calcul)\\n\\nSource : Calcul de l'IMC (poids / taille²)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__5\",\n       \"num\": \"6\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ETUDE DE CAS : En service au CHU de Treichville, vous avez en charge ce jour M. Sangaré, âgé de 45 ans pour une taille de 1,70 m. Il est très affaibli, a une langue pâteuse, se plaint de céphalées et de douleurs diverses. Il refuse de manger. Sa température est de 40°C, une TA de 11/7 cmHg pour un pouls de 100 puls/mn.\",\n       \"text\": \"Quels sont les besoins prioritaires de M. Sangaré ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Besoin d'apprendre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Besoin de maintenir la température du corps dans les limites de la normale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Besoin de dormir et se reposer\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Besoin d'éviter les dangers\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Besoin de manger et boire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Besoin de maintenir la température du corps dans les limites de la normale ; D. Besoin d'éviter les dangers\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"M. Sangaré a 40 °C de fièvre : le besoin de maintenir la température du corps dans les limites de la normale est perturbé en priorité. Très affaibli, il est exposé aux chutes et aux complications : besoin d'éviter les dangers. Le refus de manger est réel mais secondaire face à ces deux urgences.\\n\\nSource : Modèle de V. Henderson (explication en partie hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__6\",\n       \"num\": \"8\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"M. Zodo âgé de 35 ans souffre d'un paludisme grave, quel traitement lui conseillez-vous en première intention ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Sels de quinine par voie orale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Artemeter inj\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"CTA\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Sels de quinine en perfusion\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Artesunate inj\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"D. Sels de quinine en perfusion ; E. Artesunate inj\",\n       \"answerLetters\": [\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Dans le paludisme grave, l'OMS recommande l'artésunate injectable en option préférentielle, la quinine en perfusion étant utilisée en alternative. La quinine orale et les CTA servent au paludisme simple ou au relais oral, pas au traitement initial du paludisme grave. Remarque : Le protocole du cours cite aussi l'artéméther IM comme traitement parentéral initial possible ; la correction nationale ne le coche pas.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), 7-2 Le paludisme grave (p. 51-52)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__7\",\n       \"num\": \"9\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La posologie usuelle des sels de quinine étant de 24 mg/kg/j, combien de comprimé de quinimax dosé à 500mg doit prendre un patient de 60 kg par jour ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"1 comprimé\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"2 comprimés\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"3 comprimés\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 3 comprimés\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"24 mg/kg/j × 60 kg = 1 440 mg par jour ; 1 440 ÷ 500 mg = 2,88, soit 3 comprimés par jour (à répartir en 3 prises). Remarque : Le cours donne pour la quinine orale 25 mg/kg/j en 3 prises ; l'énoncé fixe 24 mg/kg/j, le résultat reste 3 comprimés.\\n\\nSource : Cours de maladies infectieuses et parasitaires, 5-1 Traitement (quinine) ; calcul de dose\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__8\",\n       \"num\": \"10\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La complication la plus fréquente dans l'ulcère gastro duodénal est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rectorragie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Hémoptysie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Hémorragie digestive haute\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Hémorragie digestive haute\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'hémorragie digestive est la complication la plus fréquente des ulcères gastro-duodénaux (30 à 40 % des hémorragies digestives hautes), sous forme d'hématémèse et/ou de méléna. La perforation est moins fréquente ; l'hémoptysie est d'origine respiratoire.\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), Ulcère gastro-duodénal – IV Complications (p. 116)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__9\",\n       \"num\": \"11\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En présence d'une forte douleur abdominale, un abdomen tendu et de la fièvre, vous pensez à :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une fièvre typhoïde\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une péritonite\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une occlusion\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Une péritonite\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Une douleur abdominale intense avec un abdomen tendu (défense, contracture = « ventre de bois ») et de la fièvre traduit une irritation péritonéale : c'est le tableau de la péritonite. L'occlusion associe plutôt arrêt des matières et des gaz et vomissements.\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), Examen physique de l'abdomen – recherche d'une irritation péritonéale (p. 102)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__10\",\n       \"num\": \"12\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une femme vient d'accoucher dans votre centre de santé, quel est l'algorithme utilisé pour son dépistage VIH ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"determine ensuite statpak\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"stat pak ensuite determine\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"determine seul ou stat pak seul\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. determine ensuite statpak\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le dépistage suit l'algorithme standard en série : Determine en premier, puis StatPak pour confirmer un résultat réactif. Un seul test ne suffit pas.\\n\\nSource : VIH L2 part 1, PrEP – dépistage par l'algorithme standard (Determine + StatPak) (p. 53)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__11\",\n       \"num\": \"13\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cette femme est déclarée séropositive au VIH 1 et 2 : cocher la réponse juste\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"nous attendons le bilan initial avant de la mettre sous traitement\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"nous la mettons sous traitement sans attendre le bilan initial\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le bilan initial est facultatif dans ce cas\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. nous la mettons sous traitement sans attendre le bilan initial\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Selon l'approche actuelle « tester et traiter », toute personne dépistée positive est mise sous TARV sans attendre le bilan initial, qui est réalisé en parallèle (il n'est pas facultatif). Les cas d'étude du cours montrent une mise sous TARV le jour même du dépistage.\\n\\nSource : Documents de révision L3 Médecine, étude de cas (mère mise sous TARV le jour du dépistage) ; complément hors cours du projet\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__12\",\n       \"num\": \"14\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel est le traitement adéquat pour la prise en charge de la mère qui refuse les contraceptifs ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"tdf 3tc dtg\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"tdf 3tc lpv\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"tdf 3tc efv\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. tdf 3tc dtg ; B. tdf 3tc lpv\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"Chez la femme en âge de procréer, la décision de prendre le DTG lui revient, après information (TDF + 3TC + DTG). Pour le VIH 1 et 2, l'alternative prévue est TDF + 3TC + LPV/r. Le TDF + 3TC + EFV n'est une alternative qu'en cas de VIH 1 seul : il ne convient pas à une femme VIH 1 et 2.\\n\\nSource : Cours VIH Licence 2 (diaporama), diapos 77-79 ; VIH L2 part 1, tableau des schémas de 1re ligne (p. 49)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__13\",\n       \"num\": \"15\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La mère n'a pas suivi de traitement ARV tout au long de sa grossesse, quel est le traitement ARV prophylactique pour le nouveau-né pendant 6 semaines ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"nevirapine seul\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"azt plus nvp\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"azt seul\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. azt plus nvp\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La mère n'a pas reçu de TARV pendant la grossesse : l'enfant est exposé à un haut risque de transmission. Si la mère est VIH 1 ou VIH 1+2, la prophylaxie est AZT + NVP pendant 6 semaines. La NVP seule ou l'AZT seul sont réservés aux enfants à faible risque. Remarque : Le document « VIH L2 part 1 » (p. 52) propose ABC + 3TC + LPV/r quand la mère n'est pas en suppression virale ; les deux cours ne disent pas la même chose.\\n\\nSource : Cours VIH Licence 2 (diaporama), diapos 89-92 (enfant exposé à haut risque)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__14\",\n       \"num\": \"16\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Malheureusement la mère n'a pas donné les médicaments convenablement au nouveau-né et la PCR à 6 semaines est revenue positive, quel traitement ARV faut-il donner au nouveau-né ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"abc 3tc lpvr granulé\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"abc 3tc lpvr sirop\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"abc 3tc lpvr comprimé\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. abc 3tc lpvr sirop\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Une PCR positive confirme l'infection de l'enfant : il faut un traitement ARV complet, ABC + 3TC + LPV/r, sous une forme pédiatrique adaptée au nourrisson qui ne peut pas avaler de comprimé.\\n\\nSource : Cours VIH Licence 2 (diaporama), diapos 83-86 (protocoles de l'enfant)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__15\",\n       \"num\": \"18\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Comment se fait la surveillance biologique de la mère avec la charge virale la première année ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"tous les six mois\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"tous les douze mois\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"tous les trois mois\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. tous les six mois\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Chez la femme nouvellement mise sous TARV, la charge virale est faite 3 mois après le début du traitement, puis répétée tous les 6 mois pendant la grossesse et jusqu'à la fin de l'allaitement si elle reste ≤ 1000 copies/ml.\\n\\nSource : VIH L2 part 1, Figure 6 : algorithme de la charge virale chez la femme enceinte/allaitante (p. 50)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__16\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Comment se fait la surveillance biologique du nouveau-né le premier semestre au niveau de la charge virale ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"tous les trois mois\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"tous les uns mois\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"tous les deux mois\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. tous les trois mois\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Chez le nourrisson infecté mis sous TARV, la charge virale est contrôlée de façon rapprochée, tous les 3 mois au cours du premier semestre, pour vérifier rapidement l'efficacité du traitement. (explication hors cours du projet)\\n\\nSource : Aucun passage trouvé dans les cours du projet\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__17\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La sage-femme ayant fait un accident d'exposition au sang avec la même patiente se retrouve chez le médecin, quelle prophylaxie le médecin lui donne-t-il ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"tdf 3tc efv\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"tdf 3tc dtg\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"tdf 3tc lpvr\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. tdf 3tc dtg ; C. tdf 3tc lpvr\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Pour un adulte (> 10 ans ou > 35 kg) victime d'un AES, la prophylaxie post-exposition associe TDF + 3TC + DTG (TLD), à débuter dans les 72 h et à poursuivre 28 jours. L'EFV n'est pas utilisé en PEP.\\n\\nSource : Cours VIH Licence 2 (diaporama), diapo 95 (TARV prophylactique en cas d'AES) ; VIH L2 part 1, p. 54\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__18\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les oedèmes des membres inférieurs résultent :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"D'une infiltration du tissu interstitiel par un liquide séreux\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"D'une infiltration du tissu interstitiel par les lipides\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"D'une infiltration du tissu interstitiel par une thrombose veineuse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. D'une infiltration du tissu interstitiel par un liquide séreux\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les œdèmes correspondent à une accumulation de liquide (de type séreux, pauvre en cellules) dans le tissu interstitiel, liée par exemple à une hausse de la pression veineuse (insuffisance cardiaque droite) ou à une baisse de la pression oncotique (hypoalbuminémie).\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), Cirrhose – pression oncotique et liquides interstitiels (p. 128) ; IVD (p. 88)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__19\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Que signifie le terme dyspnée ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Gêne respiratoire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Difficulté à inspirer par le nez\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Respiration par le nez\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Gêne respiratoire\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La dyspnée est une respiration anormale ressentie comme une gêne ou une difficulté à respirer. Elle ne se limite pas à l'inspiration par le nez.\\n\\nSource : Cours de sémiologie médicale et pathologies respiratoires, 1-2-5 La dyspnée (p. 6) ; Sémiologie respiratoire, V La dyspnée\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__20\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Que signifie polypnée ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Respiration lente\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Respiration difficile\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Respiration rapide et superficielle\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Respiration rapide et superficielle\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La polypnée est une respiration rapide et superficielle (FR > 20 cycles/mn chez l'adulte). La respiration lente est la bradypnée.\\n\\nSource : Sémiologie respiratoire, Différents types de dyspnée\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__21\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La dyspnée d'origine cardiaque est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Liée à l'effort et s'accroît avec celui-ci et disparaît quelques mn après l'arrêt de l'effort\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Liée à un effort et s'interrompt au bout de quelques heures après l'arrêt de l'effort\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Liée à un effort et s'interrompt au bout de 3 mn\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Liée à l'effort et s'accroît avec celui-ci et disparaît quelques mn après l'arrêt de l'effort\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La dyspnée d'origine cardiaque (insuffisance ventriculaire gauche) est d'abord une dyspnée d'effort : elle apparaît à l'effort, augmente avec son intensité et cède en quelques minutes au repos. Elle évolue ensuite vers une dyspnée de décubitus, puis permanente.\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), IVG – signes cliniques (p. 85) ; Cours de sémiologie médicale et pathologies respiratoires, dyspnée d'effort (p. 6)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__22\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Vous devez injecter 3,5 mg de Gentalline en IM. Sachant qu'une ampoule contient 10 mg pour 2 ml, quelle quantité prélèverez-vous ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"0,5 ml\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"0,3 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"0,7 ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 0,7 ml\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"10 mg dans 2 ml, soit 5 mg/ml. Volume = 3,5 mg ÷ 5 mg/ml = 0,7 ml. (explication hors cours du projet : calcul)\\n\\nSource : Calcul de dose (règle de trois)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__23\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Combien de types de diabète existe-t-il ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Deux types\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Un type\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Trois types\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Trois types\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"On distingue trois grands types de diabète : le type 1 (insulino-dépendant, juvénile), le type 2 (non insulino-dépendant, de la maturité) et le diabète gestationnel.\\n\\nSource : Documents de révision L3 Médecine, chapitre Diabète, QCD 13-19 (p. 27)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__24\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les signes suivants, deux relèvent du diabète de type 1, lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Amaigrissement\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Aménorrhée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Mictions fréquentes\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Hémorragie\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Dyspnée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Amaigrissement ; C. Mictions fréquentes\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Le diabète de type 1 se manifeste par une polyurie (mictions fréquentes et abondantes), une soif intense et un amaigrissement malgré une faim constante. L'aménorrhée, l'hémorragie et la dyspnée ne sont pas des signes du diabète de type 1.\\n\\nSource : Documents de révision L3 Médecine, Diabète – QCM 1 (symptômes du diabète de type 1) (p. 28)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__25\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour un patient ayant une valeur de l'hémoglobine glyquée HbA1C à 7%, quel sera son taux en glycémie ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"1,26 g/l\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"3,5% HbA1C\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"6,5 mmol/l\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"11 mmol/l\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"0,8 g/l\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. 1,26 g/l ; D. 11 mmol/l\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient 1,26 g/l et 11 mmol/l. (explication hors cours du projet) Remarque : 1,26 g/l correspond à environ 7 mmol/l, et non à 11 mmol/l : les deux valeurs cochées ne sont pas équivalentes. Dans les tables usuelles, une HbA1c de 7 % correspond à une glycémie moyenne d'environ 1,54 g/l (8,6 mmol/l). Question à revoir.\\n\\nSource : Aucun tableau de correspondance HbA1c/glycémie dans les cours du projet\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__26\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'écouvillonnage nasopharyngé se fait :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Par la voie nasale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Par la voie buccale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Par les deux voies\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Par la voie nasale\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le prélèvement nasopharyngé (par exemple pour la COVID-19) se fait par la voie nasale : l'écouvillon est introduit par une narine jusqu'au nasopharynx.\\n\\nSource : Cours de maladies infectieuses et parasitaires, COVID-19 – diagnostic biologique (écouvillonnage nasal ou pharyngé)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__27\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"On peut observer dans un épanchement pleural liquidien :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une hypersonorité\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une matité d'un hémithorax\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une abolition des vibrations vocales\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Un souffle tubaire\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Des râles crépitants\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Une matité d'un hémithorax ; C. Une abolition des vibrations vocales\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"L'épanchement pleural liquidien donne le trépied de Trousseau : matité, abolition des vibrations vocales et abolition du murmure vésiculaire. L'hypersonorité oriente vers un pneumothorax, le souffle tubaire et les râles crépitants vers une condensation.\\n\\nSource : Examen physique en pneumologie, 2- Syndrome d'épanchement liquidien pleural\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__28\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les risques suivants liés au sondage urinaire, un est faux, lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Au respect du système clos\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Non respect des règles d'asepsie lors des manipulations\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Non respect des règles d'hygiène\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Au respect du système clos\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le respect du système clos protège justement contre l'infection : ce n'est pas un risque. Le non-respect de l'asepsie et de l'hygiène favorise l'infection urinaire, le cathétérisme étant un facteur favorisant reconnu.\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), Infections des voies urinaires – généralités (p. 160)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__29\",\n       \"num\": \"32\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le but du traitement du diabète est de normaliser le taux de sucre dans le sang.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le diabète est une hyperglycémie chronique ; son traitement (régime, activité physique, médicaments, insuline) vise à ramener la glycémie dans les valeurs normales pour prévenir les complications.\\n\\nSource : Documents de révision L3 Médecine, Diabète (QCD 4, 18 ; QCM 11)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__30\",\n       \"num\": \"33\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le pancréas est une glande qui joue un rôle de régulation du sucre dans l'organisme humain.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le pancréas endocrine sécrète l'insuline, hormone qui régule la concentration de sucre dans le sang.\\n\\nSource : Documents de révision L3 Médecine, Diabète, QCD 10 et QCM 21 (p. 27-31)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__31\",\n       \"num\": \"34\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le diabète de type 2 est causé par un dysfonctionnement du pancréas.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le diabète de type 2 résulte surtout d'une mauvaise utilisation de l'insuline par l'organisme (insulino-résistance), et non d'un simple dysfonctionnement du pancréas comme dans le type 1.\\n\\nSource : Documents de révision L3 Médecine, Diabète, QCD 16 (p. 27)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__32\",\n       \"num\": \"35\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'HTA peut se révéler par des signes fonctionnels ou lors d'une consultation fortuite.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'HTA peut être découverte de façon fortuite lors d'un examen de routine ou à l'occasion de signes fonctionnels (céphalées occipitales, acouphènes, phosphènes…).\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), HTA – 3.1 Circonstances de découverte (p. 64)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__33\",\n       \"num\": \"36\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La pollakiurie porte sur la quantité d'urine émise en 24H.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La pollakiurie porte sur la fréquence des mictions (mictions trop nombreuses), et non sur la quantité d'urine. (explication hors cours du projet)\\n\\nSource : Cours sur les adénomes de la prostate, signes fonctionnels (pollakiurie nocturne et/ou diurne) ; définition hors cours du projet\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__34\",\n       \"num\": \"37\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La polyurie est portée sur la quantité des urines de 24H.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Faux ». (explication hors cours du projet)\\n\\nSource : Documents de révision L3 Médecine, Diabète, QCM 1 : « Polyurie (excrétion excessive d'urine) »\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__35\",\n       \"num\": \"38\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'incontinence urinaire est synonyme d'énurésie.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'incontinence urinaire est une perte involontaire d'urine, à tout âge. L'énurésie est une forme particulière : miction involontaire, surtout nocturne, chez l'enfant après l'âge de la propreté. Les deux termes ne sont pas synonymes. (explication hors cours du projet)\\n\\nSource : Aucune définition trouvée dans les cours du projet\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__36\",\n       \"num\": \"39\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La hernie hiatale est caractérisée par le reflux gastro-oesophagien.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La hernie hiatale est la remontée (protrusion) d'une partie de l'estomac dans le thorax à travers le hiatus œsophagien ; elle s'accompagne souvent d'un reflux gastro-œsophagien. Remarque : Le cours définit la hernie hiatale par la protrusion de l'estomac ; le reflux en est une manifestation fréquente plus que la définition.\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), Sémiologie digestive – la hernie hiatale (p. 104)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__37\",\n       \"num\": \"40\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La corticothérapie peut être considérée comme un dopage chez un sportif.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les corticoïdes figurent sur la liste des substances interdites en compétition (dopage) lorsqu'ils sont pris par voie générale sans justification médicale. (explication hors cours du projet)\\n\\nSource : Aucun passage trouvé dans les cours du projet\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__38\",\n       \"num\": \"41\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les personnes vivant avec le VIH doivent être privilégiées dans toute la société.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les personnes vivant avec le VIH ne doivent ni être discriminées ni être « privilégiées » : on recherche l'égalité, la dignité et l'accès équitable aux soins (Santé positive, dignité et prévention).\\n\\nSource : Cours VIH Licence 2 (diaporama), diapos 157-158 (SPDP : droits humains, accès équitable)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__39\",\n       \"num\": \"42\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'hôte intermédiaire de la dracunculose est un crustacé d'eau douce appelé cyclops.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La dracunculose (ver de Guinée) a pour hôte intermédiaire un petit crustacé d'eau douce (cyclops), avalé avec l'eau de boisson non filtrée ; la prévention comprend la destruction des cyclops et la filtration de l'eau. Remarque : Le cours nomme le crustacé « coronatus » dans l'épidémiologie, puis parle de « cyclops » dans la prophylaxie.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Dracunculose – 2-4 Hôte intermédiaire et VII Prophylaxie (p. 10-11)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__40\",\n       \"num\": \"43\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'ascaris peut entraîner une occlusion intestinale.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'occlusion intestinale (par un paquet de vers) fait la gravité de l'ascaridiose, avec les migrations biliaires et pancréatiques.\\n\\nSource : Documents de révision L3 Médecine, Ascaridiose, QCD 6 (p. 5)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__41\",\n       \"num\": \"44\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans les syndromes dysentériques, les germes responsables sont uniquement des bactéries.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les syndromes dysentériques sont dus soit à des bactéries (shigelles), soit à des parasites (Giardia, amibes) : pas uniquement à des bactéries.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Les syndromes dysentériques – I Généralités (p. 27)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__42\",\n       \"num\": \"45\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le prélèvement pour une gazométrie se fait dans une artère radiale ou humérale.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le prélèvement artériel pour les gaz du sang se fait le plus souvent dans l'artère radiale (que l'IDE peut ponctionner), mais aussi dans l'artère humérale ou fémorale (cette dernière par le médecin).\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), Gazométrie sanguine – IV Sites de ponction (p. 29-30)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__43\",\n       \"num\": \"46\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La contamination de la tuberculose est strictement interhumaine.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La contamination est surtout interhumaine (voie aérienne), mais l'animal malade est aussi une source : le lait de vache infecté (Mycobacterium bovis) peut transmettre la tuberculose par voie digestive. Elle n'est donc pas strictement interhumaine.\\n\\nSource : Cours de sémiologie médicale et pathologies respiratoires, Tuberculose – sources et mode de contamination (p. 72)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__44\",\n       \"num\": \"47\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'hématémèse est l'émission de sang rouge par la bouche dans un effort de vomissement.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'hématémèse est le rejet par la bouche de sang lors d'un effort de vomissement ; elle traduit une hémorragie digestive haute. Remarque : Le cours précise que le sang peut être rouge ou noir.\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), Sémiologie digestive – Hématémèse (p. 105)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j3-ide__45\",\n       \"num\": \"48\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le venin des vipéridés est neurotoxique et entraîne des paralysies généralisées.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Vrai ».\\n\\nSource : Envenimations – traitement (diaporama), Composition des venins (2) ; Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Envenimations (vipéridés / colubridés)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Médecine)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
